-- Content Foundation is additive. Existing ownership, lineups, receipts,
-- tickets, rounds, matches, and progression rows are never deleted here.

create table public.teams (
  id text primary key check (id ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  name text not null check (length(btrim(name)) between 2 and 120),
  abbreviation text not null check (length(btrim(abbreviation)) between 2 and 8),
  league text not null check (league in ('NHL', 'PWHL')),
  active boolean not null default true,
  visual_metadata jsonb not null default '{}'::jsonb
    check (jsonb_typeof(visual_metadata) = 'object'),
  source_metadata jsonb not null default '{}'::jsonb
    check (jsonb_typeof(source_metadata) = 'object'),
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  unique (id, league)
);

create index teams_league_active_name_idx
  on public.teams (league, active, name, id);

create table public.players (
  id text primary key check (id ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  name text not null check (length(btrim(name)) between 2 and 160),
  league text not null check (league in ('NHL', 'PWHL')),
  current_team_id text not null,
  nationality text check (nationality is null or nationality ~ '^[A-Z]{3}$'),
  role text not null check (role in ('skater', 'goalie')),
  primary_position text not null check (primary_position in ('LW', 'C', 'RW', 'LD', 'RD', 'G')),
  secondary_positions text[] not null default '{}'::text[]
    check (secondary_positions <@ array['LW', 'C', 'RW', 'LD', 'RD', 'G']::text[]),
  handedness text not null check (handedness in ('left', 'right', 'unknown')),
  archetype text not null check (length(btrim(archetype)) between 2 and 120),
  active boolean not null default true,
  image_reference text,
  source_metadata jsonb not null default '{}'::jsonb
    check (jsonb_typeof(source_metadata) = 'object'),
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  unique (id, league),
  foreign key (current_team_id, league)
    references public.teams(id, league) on update cascade on delete restrict,
  check (
    (role = 'goalie' and primary_position = 'G' and cardinality(secondary_positions) = 0)
    or (
      role = 'skater'
      and primary_position <> 'G'
      and not ('G' = any(secondary_positions))
      and not (primary_position = any(secondary_positions))
    )
  )
);

create index players_current_team_active_idx
  on public.players (current_team_id, active, primary_position, id);
create index players_league_position_active_idx
  on public.players (league, primary_position, active, id);

alter table public.card_catalog
  add column team_id text,
  add column card_tier text,
  add column market_availability text,
  add column abilities text[] not null default '{}'::text[],
  add column image_reference text,
  add column visual_metadata jsonb not null default '{}'::jsonb,
  add column source_metadata jsonb not null default '{"status":"legacy-unreconciled"}'::jsonb,
  add column legacy_retained boolean not null default true;

