-- END GENERATED CARD CATALOG

-- Existing stable card IDs omitted from a later generated projection remain
-- usable. They are made non-marketable when their old classification no longer
-- satisfies the new rating curve, and their provenance is explicitly audited.
do $$
begin
  if exists (
    select 1
    from public.card_catalog catalog
    left join public.players players on players.id = catalog.player_id
    where catalog.team_id is null and players.id is null
  ) then
    raise exception using
      errcode = '23503',
      message = 'The content seed does not cover every existing card player identity.';
  end if;
end;
$$;

update public.card_catalog catalog
set team_id = players.current_team_id,
    card_type = case
      when catalog.card_type = 'base' and catalog.overall between 68 and 86 then 'base'
      when not catalog.is_reward_only
        and catalog.overall between 84 and 90
        and catalog.available_from is not null and catalog.available_to is not null then 'event'
      else 'reward'
    end,
    card_tier = case
      when catalog.card_type = 'base' and catalog.overall between 68 and 86 then 'standard'
      when catalog.card_type in ('featured', 'elite', 'signature') then catalog.card_type
      else 'featured'
    end,
    market_availability = case
      when catalog.card_type = 'base' and catalog.overall between 68 and 86 then 'base-market'
      when not catalog.is_reward_only
        and catalog.overall between 84 and 90
        and catalog.available_from is not null and catalog.available_to is not null then 'event-shop'
      else 'reward-only'
    end,
    overall = case
      when catalog.card_type = 'base' and catalog.overall between 68 and 86 then catalog.overall
      when not catalog.is_reward_only
        and catalog.overall between 84 and 90
        and catalog.available_from is not null and catalog.available_to is not null then catalog.overall
      else least(catalog.overall, 90)
    end,
    price = case
      when catalog.card_type = 'base' and catalog.overall between 68 and 86 then greatest(catalog.price, 1)
      when not catalog.is_reward_only
        and catalog.overall between 84 and 90
        and catalog.available_from is not null and catalog.available_to is not null then greatest(catalog.price, 1)
      else 0
    end,
    is_permanent = not (
      not catalog.is_reward_only
      and catalog.overall between 84 and 90
      and catalog.available_from is not null and catalog.available_to is not null
    ),
    is_reward_only = not (
      (catalog.card_type = 'base' and catalog.overall between 68 and 86)
      or (
        not catalog.is_reward_only
        and catalog.overall between 84 and 90
        and catalog.available_from is not null and catalog.available_to is not null
      )
    ),
    image_reference = coalesce(catalog.image_reference, 'placeholder:player/' || catalog.player_id),
    visual_metadata = case
      when catalog.visual_metadata = '{}'::jsonb then jsonb_build_object(
        'treatment', 'neutral-placeholder',
        'accent', '#6f8296',
        'frame', case
          when catalog.card_type in ('featured', 'elite', 'signature') then catalog.card_type
          when catalog.card_type = 'base' and catalog.overall between 68 and 86 then 'standard'
          else 'featured'
        end
      )
      else catalog.visual_metadata
    end,
    source_metadata = jsonb_build_object(
      'status', 'legacy-retained',
      'legacyCardType', catalog.card_type,
      'reconciledAt', '2026-07-14'
    ),
    legacy_retained = true,
    available_from = case
      when not catalog.is_reward_only
        and catalog.overall between 84 and 90
        and catalog.available_from is not null and catalog.available_to is not null
      then catalog.available_from
      else null
    end,
    available_to = case
      when not catalog.is_reward_only
        and catalog.overall between 84 and 90
        and catalog.available_from is not null and catalog.available_to is not null
      then catalog.available_to
      else null
    end
from public.players players
where catalog.player_id = players.id
  and catalog.team_id is null;

alter table public.card_catalog
  alter column team_id set not null,
  alter column card_tier set not null,
  alter column market_availability set not null,
  alter column image_reference set not null;

alter table public.card_catalog
  drop constraint if exists card_catalog_card_type_check;
alter table public.card_catalog
  add constraint card_catalog_card_type_check
    check (card_type in ('starter', 'base', 'event', 'reward')) not valid,
  add constraint card_catalog_card_tier_check
    check (card_tier in ('starter', 'standard', 'featured', 'elite', 'signature')) not valid,
  add constraint card_catalog_market_availability_check
    check (market_availability in ('unavailable', 'base-market', 'event-shop', 'reward-only')) not valid,
  add constraint card_catalog_content_contract_check check (
    (
      card_type = 'starter'
      and card_tier = 'starter'
      and overall between 68 and 76
      and price = 0
      and market_availability = 'unavailable'
      and is_permanent
      and not is_reward_only
      and available_from is null
      and available_to is null
    )
    or (
      card_type = 'base'
      and card_tier = 'standard'
      and overall between 68 and 86
      and price > 0
      and market_availability = 'base-market'
      and is_permanent
      and not is_reward_only
      and available_from is null
      and available_to is null
    )
    or (
      card_type = 'event'
      and card_tier in ('featured', 'elite', 'signature')
      and overall between 84 and 90
      and price > 0
      and market_availability = 'event-shop'
      and not is_permanent
      and not is_reward_only
      and available_from is not null
      and available_to is not null
      and available_from < available_to
    )
    or (
      card_type = 'reward'
      and card_tier in ('featured', 'elite', 'signature')
      and overall between 68 and 90
      and price = 0
      and market_availability = 'reward-only'
      and is_permanent
      and is_reward_only
      and available_from is null
      and available_to is null
    )
  ) not valid,
  add constraint card_catalog_visual_metadata_object_check
    check (jsonb_typeof(visual_metadata) = 'object') not valid,
  add constraint card_catalog_source_metadata_object_check
    check (jsonb_typeof(source_metadata) = 'object') not valid,
  add constraint card_catalog_player_league_fkey
    foreign key (player_id, league) references public.players(id, league)
    on update cascade on delete restrict not valid,
  add constraint card_catalog_team_league_fkey
    foreign key (team_id, league) references public.teams(id, league)
    on update cascade on delete restrict not valid;

create unique index card_catalog_team_card_key
  on public.card_catalog (team_id, card_id);
create index card_catalog_player_id_idx
  on public.card_catalog (player_id);
create index card_catalog_team_type_overall_idx
  on public.card_catalog (team_id, card_type, overall desc, card_id);
create index card_catalog_market_availability_idx
  on public.card_catalog (
    market_availability, is_active, set_id, available_from, available_to, card_id
  );

-- Remove only the superseded internal Oilers starter configuration. No
-- account-owned card, lineup slot, or receipt row is touched.
delete from public.starter_team_cards
where team_id = 'edmonton-oilers'
  and card_id in (
    'nhl-brady-tkachuk-base',
    'nhl-connor-mcdavid-base',
    'nhl-mikko-rantanen-base',
    'nhl-rasmus-dahlin-base',
    'nhl-evan-bouchard-base',
    'nhl-igor-shesterkin-base'
  );

-- BEGIN GENERATED STARTER SQUADS
