alter table public.starter_team_cards
  add constraint starter_team_cards_team_fkey
    foreign key (team_id) references public.teams(id)
    on update cascade on delete restrict not valid,
  add constraint starter_team_cards_team_card_fkey
    foreign key (team_id, card_id) references public.card_catalog(team_id, card_id)
    on update cascade on delete restrict not valid;

do $$
begin
  if not exists (select 1 from public.teams where active) or exists (
    select teams.id
    from public.teams teams
    where teams.active
      and (
        select count(*) from public.starter_team_cards starter where starter.team_id = teams.id
      ) <> 6
  ) or exists (
    select teams.id
    from public.teams teams
    cross join (values ('LW'), ('C'), ('RW'), ('LD'), ('RD'), ('G')) required(slot)
    where teams.active and not exists (
      select 1
      from public.starter_team_cards starter
      join public.card_catalog catalog
        on catalog.card_id = starter.card_id
       and catalog.team_id = starter.team_id
       and catalog.card_type = 'starter'
       and catalog.market_availability = 'unavailable'
       and catalog.is_active
       and starter.slot = any(catalog.eligible_positions)
      where starter.team_id = teams.id and starter.slot = required.slot
    )
  ) then
    raise exception using
      errcode = '23514',
      message = 'Every active team requires six valid, non-marketable starter cards.';
  end if;
end;
$$;

alter table public.card_catalog validate constraint card_catalog_card_type_check;
alter table public.card_catalog validate constraint card_catalog_card_tier_check;
alter table public.card_catalog validate constraint card_catalog_market_availability_check;
alter table public.card_catalog validate constraint card_catalog_content_contract_check;
alter table public.card_catalog validate constraint card_catalog_visual_metadata_object_check;
alter table public.card_catalog validate constraint card_catalog_source_metadata_object_check;
alter table public.card_catalog validate constraint card_catalog_player_league_fkey;
alter table public.card_catalog validate constraint card_catalog_team_league_fkey;
alter table public.starter_team_cards validate constraint starter_team_cards_team_fkey;
alter table public.starter_team_cards validate constraint starter_team_cards_team_card_fkey;

create table public.starter_grant_receipts (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  team_id text not null references public.teams(id) on update cascade on delete restrict,
  lineup_id uuid not null,
  card_snapshot jsonb not null check (
    jsonb_typeof(card_snapshot) = 'array' and jsonb_array_length(card_snapshot) = 6
  ),
  credits_granted integer not null check (credits_granted = 1000),
  origin text not null check (origin = 'new-account'),
  grant_version text not null check (grant_version = 'content-foundation-v1'),
  claimed_at timestamptz not null default clock_timestamp(),
  foreign key (lineup_id, user_id)
    references public.lineups(id, user_id) on update cascade on delete restrict
);

create index starter_grant_receipts_team_claimed_idx
  on public.starter_grant_receipts (team_id, claimed_at desc);
create index starter_grant_receipts_lineup_user_idx
  on public.starter_grant_receipts (lineup_id, user_id);

create table public.starter_migration_audits (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  state text not null check (state in ('manual-review', 'resolved-preserved')),
  legacy_team_id text,
  legacy_claimed_at timestamptz not null,
  legacy_lineup_id uuid,
  credits_at_audit integer not null check (credits_at_audit >= 0),
  ownership_snapshot jsonb not null check (jsonb_typeof(ownership_snapshot) = 'array'),
  open_ticket_snapshot jsonb not null check (jsonb_typeof(open_ticket_snapshot) = 'array'),
  reason text not null check (length(btrim(reason)) between 1 and 500),
  audited_at timestamptz not null default clock_timestamp(),
  reviewed_at timestamptz,
  check (
    (state = 'manual-review' and reviewed_at is null)
    or (state = 'resolved-preserved' and reviewed_at is not null)
  )
);

-- Legacy grants have no trustworthy per-card provenance. Snapshot and preserve
-- them for manual review; do not remove ownership, change Credits, switch an
-- active lineup, or disturb a referenced open match ticket.
insert into public.starter_migration_audits (
  user_id, state, legacy_team_id, legacy_claimed_at, legacy_lineup_id,
  credits_at_audit, ownership_snapshot, open_ticket_snapshot, reason
)
select
  profiles.id,
  'manual-review',
  profiles.favorite_team_id,
  profiles.starter_claimed_at,
  profiles.starter_lineup_id,
  profiles.credits,
  coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'card_id', owned.card_id,
        'quantity', owned.quantity,
        'acquired_at', owned.acquired_at
      ) order by owned.card_id
    )
    from public.user_cards owned
    where owned.user_id = profiles.id
  ), '[]'::jsonb),
  coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'ticket_id', tickets.id,
        'client_match_id', tickets.client_match_id,
        'lineup_id', tickets.lineup_id,
        'status', tickets.status,
        'started_at', tickets.started_at
      ) order by tickets.started_at, tickets.id
    )
    from public.match_tickets tickets
    where tickets.user_id = profiles.id and tickets.status = 'open'
  ), '[]'::jsonb),
  'Legacy starter provenance is ambiguous; ownership and account state were preserved.'
from public.profiles profiles
where profiles.starter_claimed_at is not null
  and not exists (
    select 1 from public.starter_grant_receipts receipts where receipts.user_id = profiles.id
  )
on conflict (user_id) do nothing;

alter table public.teams enable row level security;
alter table public.players enable row level security;
alter table public.starter_grant_receipts enable row level security;
alter table public.starter_migration_audits enable row level security;

create policy "teams_select_authenticated"
  on public.teams for select to authenticated using (true);
create policy "players_select_authenticated"
  on public.players for select to authenticated using (true);
create policy "starter_grant_receipts_select_own"
  on public.starter_grant_receipts for select to authenticated
  using ((select auth.uid()) = user_id);
create policy "starter_migration_audits_select_own"
  on public.starter_migration_audits for select to authenticated
  using ((select auth.uid()) = user_id);

revoke all on table public.teams from public, anon, authenticated;
revoke all on table public.players from public, anon, authenticated;
revoke all on table public.starter_grant_receipts from public, anon, authenticated;
revoke all on table public.starter_migration_audits from public, anon, authenticated;
grant select on table public.teams to authenticated;
grant select on table public.players to authenticated;
grant select on table public.starter_grant_receipts to authenticated;
grant select on table public.starter_migration_audits to authenticated;

revoke all on function public.set_updated_at() from public, anon, authenticated;

-- Market membership is now explicit. Starter and reward cards never become
-- offers, and event cards must be inside both the event rotation and card UTC
-- availability window.
create or replace function public.current_market_offers(at_time timestamptz)
returns table (
  offer_id text,
  card_id text,
  source text,
  regular_price integer,
  price integer,
  event_id text,
  placement text,
  starts_at timestamptz,
  ends_at timestamptz
)
language sql
stable
set search_path = ''
as $$
  with market_clock as (
    select
      date_trunc('week', at_time at time zone 'UTC') as starts_utc,
      floor(extract(epoch from (
        date_trunc('week', at_time at time zone 'UTC') - timestamp '2026-01-05 00:00:00'
      )) / 604800)::bigint as week_index
  ), active_event as (
    select
      events.id,
      market_clock.starts_utc,
      market_clock.week_index,
      floor(market_clock.week_index::numeric / 10)::bigint as occurrence_index
    from market_clock
    join public.event_definitions events
      on events.rotation_order = (((market_clock.week_index % 10) + 10) % 10)::integer
    where events.is_active
  ), eligible_event_pool as (
    select
      cards.card_id,
      cards.price,
      cards.available_from,
      cards.available_to,
      active_event.id as event_id,
      active_event.starts_utc,
      active_event.week_index,
      active_event.occurrence_index
    from active_event
    join public.card_catalog cards on cards.set_id = active_event.id
    where cards.is_active
      and cards.card_type = 'event'
      and cards.market_availability = 'event-shop'
      and not cards.is_permanent
      and not cards.is_reward_only
      and cards.available_from <= at_time
      and at_time < cards.available_to
  ), ranked_event_pool as (
    select
      eligible_event_pool.*,
      row_number() over (
        partition by eligible_event_pool.event_id
        order by md5(
          'rink-rivals:' || eligible_event_pool.event_id || ':v1:' ||
            eligible_event_pool.card_id
        ), eligible_event_pool.card_id
      ) - 1 as deck_index,
      count(*) over (partition by eligible_event_pool.event_id) as pool_count
    from eligible_event_pool
  ), event_pool as (
    select
      ranked_event_pool.*,
      rotated.selection_index + 1 as offer_number,
      least(6::bigint, ranked_event_pool.pool_count) as offer_count
    from ranked_event_pool
    cross join lateral (
      select (
        ranked_event_pool.deck_index - (
          (
            (ranked_event_pool.occurrence_index * 6) % ranked_event_pool.pool_count +
              ranked_event_pool.pool_count
          ) % ranked_event_pool.pool_count
        ) + ranked_event_pool.pool_count
      ) % ranked_event_pool.pool_count as selection_index
    ) rotated
    where rotated.selection_index < least(6::bigint, ranked_event_pool.pool_count)
  )
  select
    'base-market:' || cards.card_id,
    cards.card_id,
    'base_market'::text,
    cards.price,
    cards.price,
    null::text,
    'standard'::text,
    null::timestamptz,
    null::timestamptz
  from public.card_catalog cards
  where cards.is_active
    and cards.card_type = 'base'
    and cards.market_availability = 'base-market'
    and cards.is_permanent
    and not cards.is_reward_only
    and cards.available_from is null
    and cards.available_to is null
  union all
  select
    'event-shop:' || event_pool.event_id || ':' ||
      to_char(event_pool.starts_utc, 'YYYY-MM-DD') || ':' || event_pool.card_id,
    event_pool.card_id,
    'event_shop'::text,
    event_pool.price,
    case when event_pool.offer_number = 1 + (
      ((event_pool.week_index % event_pool.offer_count) + event_pool.offer_count) % event_pool.offer_count
    ) then greatest(1, round(event_pool.price * 0.85)::integer) else event_pool.price end,
    event_pool.event_id,
    case when event_pool.offer_number = 1 + (
      ((event_pool.week_index % event_pool.offer_count) + event_pool.offer_count) % event_pool.offer_count
    ) then 'spotlight'::text else 'standard'::text end,
    greatest(
      event_pool.starts_utc at time zone 'UTC',
      event_pool.available_from
    ),
    least(
      (event_pool.starts_utc + interval '7 days') at time zone 'UTC',
      event_pool.available_to
    )
  from event_pool;
$$;

revoke all on function public.current_market_offers(timestamptz)
  from public, anon, authenticated;

-- New accounts can freely select any complete active team. Existing legacy
-- claims remain untouched and are held for manual review because their original
-- six-card provenance is not trustworthy.
create or replace function public.claim_starter_team(selected_team_id text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_variable
declare
  requesting_user_id uuid := auth.uid();
  normalized_team_id text := btrim(claim_starter_team.selected_team_id);
  profile public.profiles%rowtype;
  existing_receipt public.starter_grant_receipts%rowtype;
  selected_team public.teams%rowtype;
  selected_mode text;
  created_lineup_id uuid;
  claim_time timestamptz;
  starter_card_count integer;
  starter_snapshot jsonb;
begin
  if requesting_user_id is null then
    raise exception using errcode = '42501',
      message = 'Authentication required to claim a starter team.';
  end if;
  if normalized_team_id is null or normalized_team_id = '' then
    raise exception using errcode = '22023', message = 'A starter team id is required.';
  end if;

  select * into profile
  from public.profiles profiles
  where profiles.id = requesting_user_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'Profile not found.';
  end if;

  select * into existing_receipt
  from public.starter_grant_receipts receipts
  where receipts.user_id = requesting_user_id;
  if found then
    if existing_receipt.team_id <> normalized_team_id then
      raise exception using errcode = 'P0001',
        message = 'A different starter team has already been claimed.';
    end if;
    return existing_receipt.lineup_id;
  end if;

  if profile.starter_claimed_at is not null then
    insert into public.starter_migration_audits (
      user_id, state, legacy_team_id, legacy_claimed_at, legacy_lineup_id,
      credits_at_audit, ownership_snapshot, open_ticket_snapshot, reason
    ) values (
      requesting_user_id,
      'manual-review',
      profile.favorite_team_id,
      profile.starter_claimed_at,
      profile.starter_lineup_id,
      profile.credits,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'card_id', owned.card_id,
            'quantity', owned.quantity,
            'acquired_at', owned.acquired_at
          ) order by owned.card_id
        )
        from public.user_cards owned
        where owned.user_id = requesting_user_id
      ), '[]'::jsonb),
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'ticket_id', tickets.id,
            'client_match_id', tickets.client_match_id,
            'lineup_id', tickets.lineup_id,
            'status', tickets.status,
            'started_at', tickets.started_at
          ) order by tickets.started_at, tickets.id
        )
        from public.match_tickets tickets
        where tickets.user_id = requesting_user_id and tickets.status = 'open'
      ), '[]'::jsonb),
      'Legacy starter provenance is ambiguous; ownership and account state were preserved.'
    ) on conflict (user_id) do nothing;

    if profile.favorite_team_id = normalized_team_id
      and profile.starter_lineup_id is not null
      and exists (
        select 1 from public.lineups lineups
        where lineups.id = profile.starter_lineup_id
          and lineups.user_id = requesting_user_id
      ) then
      return profile.starter_lineup_id;
    end if;

    raise exception using errcode = 'P0001',
      message = 'Legacy starter claim requires manual review.';
  end if;

  select * into selected_team
  from public.teams teams
  where teams.id = normalized_team_id and teams.active;
  if not found then
    raise exception using errcode = '22023', message = 'Unknown starter team.';
  end if;

  select count(*), jsonb_agg(
    jsonb_build_object(
      'slot', starter.slot,
      'card_id', catalog.card_id,
      'player_id', catalog.player_id,
      'team_id', catalog.team_id,
      'overall', catalog.overall
    ) order by starter.slot
  ) into starter_card_count, starter_snapshot
  from public.starter_team_cards starter
  join public.card_catalog catalog
    on catalog.card_id = starter.card_id
   and catalog.team_id = starter.team_id
  where starter.team_id = normalized_team_id
    and catalog.card_type = 'starter'
    and catalog.card_tier = 'starter'
    and catalog.market_availability = 'unavailable'
    and catalog.is_active
    and starter.slot = any(catalog.eligible_positions);

  if starter_card_count <> 6 or exists (
    select required.slot
    from (values ('LW'), ('C'), ('RW'), ('LD'), ('RD'), ('G')) required(slot)
    where not exists (
      select 1 from public.starter_team_cards starter
      where starter.team_id = normalized_team_id and starter.slot = required.slot
    )
  ) then
    raise exception using errcode = '22023',
      message = 'Unknown or incomplete starter team.';
  end if;

  claim_time := clock_timestamp();
  selected_mode := case selected_team.league
    when 'NHL' then 'nhl-circuit'
    when 'PWHL' then 'pwhl-circuit'
  end;

  insert into public.user_cards (user_id, card_id, quantity, acquired_at)
  select requesting_user_id, starter.card_id, 1, claim_time
  from public.starter_team_cards starter
  where starter.team_id = normalized_team_id
  on conflict on constraint user_cards_pkey do update
    set quantity = greatest(public.user_cards.quantity, 1);

  update public.lineups lineups
  set is_active = false, updated_at = claim_time
  where lineups.user_id = requesting_user_id
    and lineups.mode = selected_mode
    and lineups.is_active;

  insert into public.lineups (user_id, name, mode, is_active, created_at, updated_at)
  values (
    requesting_user_id,
    selected_team.name || ' Starter',
    selected_mode,
    true,
    claim_time,
    claim_time
  ) returning id into created_lineup_id;

  insert into public.lineup_slots (lineup_id, user_id, slot, card_id, created_at)
  select created_lineup_id, requesting_user_id, starter.slot, starter.card_id, claim_time
  from public.starter_team_cards starter
  where starter.team_id = normalized_team_id;

  insert into public.starter_grant_receipts (
    user_id, team_id, lineup_id, card_snapshot, credits_granted,
    origin, grant_version, claimed_at
  ) values (
    requesting_user_id, normalized_team_id, created_lineup_id, starter_snapshot,
    1000, 'new-account', 'content-foundation-v1', claim_time
  );

  update public.profiles profiles
  set favorite_team_id = normalized_team_id,
      starter_claimed_at = claim_time,
      starter_lineup_id = created_lineup_id,
      onboarding_completed = true,
      credits = profiles.credits + 1000,
      updated_at = claim_time
  where profiles.id = requesting_user_id;

  return created_lineup_id;
end;
$$;

revoke all on function public.claim_starter_team(text)
  from public, anon, authenticated;
grant execute on function public.claim_starter_team(text) to authenticated;
